import 'package:flutter/material.dart';

class PillarLesson {
  const PillarLesson({
    required this.id,
    required this.title,
    required this.icon,
    required this.explanation,
    required this.importance,
    required this.verse,
    required this.reference,
    required this.example,
    this.hadith,
    this.hadithSource,
  });

  final String id, title, explanation, importance, verse, reference, example;
  final IconData icon;
  final String? hadith, hadithSource;
}

class PillarCategory {
  const PillarCategory(this.title, this.subtitle, this.color, this.lessons);
  final String title, subtitle;
  final Color color;
  final List<PillarLesson> lessons;
}

const islamPillars = PillarCategory('أَرْكَان الْإِسْلَام', 'أعمال ظاهرة يقوم عليها الْإِسْلَام', Color(0xFF36765D), [
  PillarLesson(id:'shahada',title:'الشهادتان',icon:Icons.verified_rounded,explanation:'أن تشهد بصدق أن لا معبود بحق إلا الله، وأن محمدًا رَسُول الله؛ فتفرد اللَّه بالعبادة وتتبع رسوله ﷺ.',importance:'هي أول أَرْكَان الْإِسْلَام وأساس الدخول فيه، وتجمع أصل التَّوْحِيد واتباع الرسالة.',verse:'فَاعْلَمْ أَنَّهُ لَا إِلَٰهَ إِلَّا اللَّهُ',reference:'سُورَة محمد، الْآيَة ١٩',example:'تظهر في حياتك بإخلاص الدُّعَاء والعبادة لله، والاقتداء بهدي النَّبِيّ ﷺ.',hadith:'بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ.',hadithSource:'صحيح البخاري، حديث ٨'),
  PillarLesson(id:'prayer',title:'إقام الصَّلَاة',icon:Icons.mosque_rounded,explanation:'المحافظة على الصَّلَوَات المفروضة وأداؤها في أوقاتها كما علّمنا رَسُول اللَّه ﷺ.',importance:'صلة متجددة بين العبد وربه، وقد أمر اللَّه بالمحافظة عليها.',verse:'إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا',reference:'سُورَة النساء، الْآيَة ١٠٣',example:'تستعد للصلاة عند دخول وقتها، وتؤديها بخشوع وتتعلم أحكامها.',hadith:'صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي.',hadithSource:'صحيح البخاري، حديث ٦٣١'),
  PillarLesson(id:'zakat',title:'إيتاء الزَّكَاة',icon:Icons.volunteer_activism_rounded,explanation:'إخراج القدر الواجب من المال لمستحقيه عند تحقق شروطه، وفق أحكام الزَّكَاة.',importance:'عبادة مالية تطهر النفس والمال وتعين المحتاجين، وهي حق واجب في أموال مخصوصة.',verse:'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ',reference:'سُورَة البقرة، الْآيَة ٤٣',example:'إذا بلغ مالك النصاب وحال عليه الحول في الأموال التي يشترط فيها ذلك، تسأل أهل الْعِلْم وتحسب زكاته.',hadith:'فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً فِي أَمْوَالِهِمْ، تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ.',hadithSource:'صحيح البخاري، حديث ١٣٩٥'),
  PillarLesson(id:'fasting',title:'صوم رمضان',icon:Icons.nights_stay_rounded,explanation:'الإمساك عن المفطرات من طلوع الْفَجْر إلى غروب الشمس بنية الْعِبَادَة في شهر رمضان.',importance:'فرضه اللَّه على المؤمنين، وفيه تدريب على التقوى والصبر.',verse:'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ',reference:'سُورَة البقرة، الْآيَة ١٨٣',example:'تنوي الصيام، وتمسك عن المفطرات نهار رمضان، وتحسن إلى الناس وتكثر من الطاعات.',hadith:'مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.',hadithSource:'صحيح البخاري، حديث ٣٨'),
  PillarLesson(id:'hajj',title:'حج البيت',icon:Icons.flight_rounded,explanation:'قصد الْمَسْجِد الحرام لأداء مناسك الْحَجّ في وقتها، وهو واجب مرة في العمر على الْمُسْلِم المستطيع.',importance:'عبادة عظيمة تجمع المسلمين وتذكرهم بالتوحيد والمساواة، والاستطاعة شرط لوجوبه.',verse:'وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا',reference:'سُورَة آل عمران، الْآيَة ٩٧',example:'من استطاع بدنيًا وماليًا وأَمِن الطريق، يتعلم المناسك ويؤدي الْحَجّ مرة.',hadith:'وَالْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ.',hadithSource:'صحيح البخاري، حديث ١٧٧٣'),
]);

const imanPillars = PillarCategory('أَرْكَان الْإِيمَان', 'أصول الاعتقاد التي يؤمن بها الْمُسْلِم', Color(0xFF80633A), [
  PillarLesson(id:'allah',title:'الْإِيمَان بالله',icon:Icons.auto_awesome_rounded,explanation:'التصديق بوجود اللَّه وربوبيته وألوهيته وأسمائه وصفاته كما يليق بجلاله، وإفراده بالعبادة.',importance:'هو أصل الْإِيمَان ومنه تتفرع عبادة اللَّه وحده والتوكل عليه ومحبته.',verse:'فَاعْلَمْ أَنَّهُ لَا إِلَٰهَ إِلَّا اللَّهُ',reference:'سُورَة محمد، الْآيَة ١٩',example:'تدعو اللَّه وحده، وتشكره على نعمه، وتتوكل عليه مع الأخذ بالأسباب.'),
  PillarLesson(id:'angels',title:'الْإِيمَان بالملائكة',icon:Icons.air_rounded,explanation:'التصديق بأن الْمَلَائِكَة عباد لله خلقهم، يؤمن الْمُسْلِم بمن سمى اللَّه منهم وما صح من صفاتهم وأعمالهم.',importance:'الْإِيمَان بهم جزء مما أمر اللَّه بالإيمان به، وهم لا يعصون اللَّه فيما أمرهم.',verse:'كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ',reference:'سُورَة البقرة، الْآيَة ٢٨٥',example:'تؤمن بوجودهم كما أخبر الوحي، وتستشعر أن اللَّه مطلع على عملك.'),
  PillarLesson(id:'books',title:'الْإِيمَان بالكتب',icon:Icons.menu_book_rounded,explanation:'التصديق بأن اللَّه أنزل كتبًا على رسله هداية للناس، وأن الْقُرْآن كلام اللَّه وآخر كتبه المحفوظ.',importance:'الكتب تعرفنا بما أمر اللَّه به، والقرآن مرجع المسلمين وهدايتهم.',verse:'نَزَّلَ عَلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ',reference:'سُورَة آل عمران، الْآيَة ٣',example:'تقرأ الْقُرْآن بتدبر وتسعى للعمل به، وتؤمن بما أخبر اللَّه عن كتبه السابقة.'),
  PillarLesson(id:'messengers',title:'الْإِيمَان بالرسل',icon:Icons.campaign_rounded,explanation:'التصديق بأن اللَّه أرسل رسلًا لهداية الناس، والإيمان بهم جميعًا، وأن محمدًا ﷺ خاتمهم.',importance:'بلّغ الرسل رسالة اللَّه ودعوا إلى عبادته، واتباع محمد ﷺ واجب على أمته.',verse:'وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ',reference:'سُورَة النحل، الْآيَة ٣٦',example:'تتعلم سيرة النَّبِيّ ﷺ وتتبع سنته، وتحترم جميع الرسل الذين ذكرهم اللَّه.'),
  PillarLesson(id:'afterlife',title:'الْإِيمَان باليوم الآخر',icon:Icons.wb_twilight_rounded,explanation:'التصديق بالبعث والحساب والجزاء والجنة والنار وسائر ما صح من أخبار الْآخِرَة.',importance:'يذكر الإنسان بمسؤوليته عن عمله ويعينه على اختيار الخير.',verse:'وَبِالْآخِرَةِ هُمْ يُوقِنُونَ',reference:'سُورَة البقرة، الْآيَة ٤',example:'تراقب أمانتك وأعمالك، وتبادر إلى التَّوْبَة والخير رجاء لقاء اللَّه.'),
  PillarLesson(id:'qadar',title:'الْإِيمَان بالقدر خيره وشره',icon:Icons.balance_rounded,explanation:'الْإِيمَان بأن اللَّه علم كل شيء وكتبه وشاءه وخلقه، مع مسؤولية الإنسان عن اختياره وعمله.',importance:'يعلم الْمُسْلِم أن الأمور بقدر الله، فيشكره عند النِّعْمَة ويصبر عند المصيبة مع السعي والعمل.',verse:'إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ',reference:'سُورَة القمر، الْآيَة ٤٩',example:'تجتهد وتخطط وتأخذ بالأسباب، ثم ترضى بقضاء اللَّه وتستعين به.'),
]);
